if(!is_file(__DIR__.'/installed.lock')) { header('Location: installation/install.php'); exit; }
$page=$_GET['page']??'home';
$allowed=['home','shop','categories','product','search','cart','checkout','login','register','logout','account','orders','track','wishlist','compare','contact','about','faq','privacy','terms','returns','shipping','cancellation','blog','deals','flash-sales','best-sellers','new-arrivals'];
if(!in_array($page,$allowed,true)) $page='404';
$pageTitle=ucwords(str_replace('-',' ',$page==='home'?'':$page));
if($page==='logout'){session_destroy();session_start();flash('success','You have signed out.');go('index.php');}
if($page==='login' && $_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$stmt=db()->prepare('SELECT id,name,email,password_hash,role,is_active FROM users WHERE email=? LIMIT 1');$stmt->execute([$email]);$u=$stmt->fetch();if($u && $u['is_active'] && password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=$u;flash('success','Welcome back.');go('index.php?page=account');}flash('error','Email or password is incorrect.');go('index.php?page=login');}
if($page==='register' && $_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10){flash('error','Enter a valid name/email and password of at least 10 characters.');go('index.php?page=register');}try{$s=db()->prepare("INSERT INTO users(name,email,password_hash,role,is_active,created_at) VALUES(?,?,?,'customer',1,NOW())");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('success','Account created. Please sign in.');go('index.php?page=login');}catch(PDOException $e){flash('error','This email may already be registered.');go('index.php?page=register');}}
if($page==='cart' && $_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['product_id']??0);if($action==='add'&&$id>0){$s=db()->prepare('SELECT id,stock FROM products WHERE id=? AND status="published"');$s->execute([$id]);$p=$s->fetch();if($p){$_SESSION['cart'][$id]['qty']=min((int)$p['stock'],(int)($_SESSION['cart'][$id]['qty']??0)+max(1,(int)($_POST['qty']??1)));flash('success','Product added to cart.');}}elseif($action==='remove'){unset($_SESSION['cart'][$id]);}go('index.php?page=cart');}
if($page==='checkout' && $_SERVER['REQUEST_METHOD']==='POST'){require_login();verify_csrf();$cart=cart_items();if(!$cart){flash('error','Your cart is empty.');go('index.php?page=cart');}$pdo=db();try{$pdo->beginTransaction();$total=0;$rows=[];foreach($cart as $id=>$line){$s=$pdo->prepare('SELECT id,name,price,stock FROM products WHERE id=? FOR UPDATE');$s->execute([(int)$id]);$p=$s->fetch();if(!$p||(int)$p['stock']<(int)$line['qty'])throw new RuntimeException('Stock unavailable for '.($p['name']??'a product'));$rows[]=['p'=>$p,'qty'=>(int)$line['qty']];$total+=(float)$p['price']*(int)$line['qty'];}$ship= (float)($_POST['shipping_fee']??0);$total+=$ship;$orderNo='RMS-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare('INSERT INTO orders(order_number,user_id,customer_name,phone,address,city,subtotal,shipping_fee,total,payment_method,payment_status,order_status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?, "pending","pending",NOW())');$s->execute([$orderNo,$_SESSION['user']['id'],trim($_POST['customer_name']??''),trim($_POST['phone']??''),trim($_POST['address']??''),trim($_POST['city']??''),$total-$ship,$ship,$total,$_POST['payment_method']??'cod']);$oid=(int)$pdo->lastInsertId();foreach($rows as $r){$p=$r['p'];$q=$r['qty'];$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?)')->execute([$oid,$p['id'],$p['name'],$p['price'],$q,$p['price']*$q]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$q,$p['id']]);}$pdo->commit();$_SESSION['cart']=[];flash('success','Order placed. Your order number is '.$orderNo);go('index.php?page=orders');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());go('index.php?page=checkout');}}
require __DIR__.'/includes/header.php';
switch($page){
case 'home':
 echo '<section class="hero"><div><span class="eyebrow">ROYAL MARKETPLACE · FAISALABAD</span><h1>Everything you need.<br><em>All in one place.</em></h1><p>Mobiles, printing supplies, sublimation products, customized gifts and everyday essentials.</p><a class="btn" href="index.php?page=shop">Start Shopping</a></div><div class="hero-art"><b>ROYAL</b><strong>DEALS</strong><small>WHOLESALE · RETAIL · CUSTOM PRINTING</small></div></section><section class="trust"><div>🚚 Pakistan-wide delivery options</div><div>🔒 Secure customer accounts</div><div>🎁 Custom printing & gifts</div><div>☎ '.e(APP_PHONE).'</div></section>';
 echo '<div class="section-head"><h2>Featured products</h2><a href="index.php?page=shop">View all →</a></div>'; render_products(db()->query("SELECT * FROM products WHERE status='published' AND featured=1 ORDER BY id DESC LIMIT 8")->fetchAll());
 echo '<div class="section-head"><h2>New arrivals</h2><a href="index.php?page=new-arrivals">View all →</a></div>';render_products(db()->query("SELECT * FROM products WHERE status='published' ORDER BY id DESC LIMIT 8")->fetchAll());break;
case 'shop': case 'deals': case 'flash-sales': case 'best-sellers': case 'new-arrivals':
 $where="status='published'";if($page==='deals'||$page==='flash-sales')$where.=" AND sale_price IS NOT NULL AND sale_price>0";$order=$page==='best-sellers'?'sold_count DESC':'id DESC';$s=db()->query("SELECT * FROM products WHERE $where ORDER BY $order LIMIT 100");echo '<h1>'.e($pageTitle?:'Shop All Products').'</h1>';render_products($s->fetchAll());break;
case 'categories':$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();echo '<h1>All Categories</h1><div class="category-grid">';foreach($cats as $c)echo '<a class="category" href="index.php?page=shop&category='.(int)$c['id'].'">'.e($c['name']).'</a>';echo '</div>';break;
case 'search':$q=trim($_GET['q']??'');$s=db()->prepare("SELECT * FROM products WHERE status='published' AND (name LIKE ? OR sku LIKE ? OR description LIKE ?) ORDER BY id DESC LIMIT 100");$like='%'.$q.'%';$s->execute([$like,$like,$like]);echo '<h1>Search results for “'.e($q).'”</h1>';render_products($s->fetchAll());break;
case 'product':$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM products WHERE id=? AND status="published"');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);echo '<h1>Product not found</h1>';break;}echo '<div class="product-detail"><div class="product-photo">'.($p['image']?'<img src="'.e(url($p['image'])).'" alt="'.e($p['name']).'">':'🛍️').'</div><div><small>'.e($p['sku']).'</small><h1>'.e($p['name']).'</h1><p>'.nl2br(e($p['description'])).'</p><h2>'.money($p['sale_price']?:$p['price']).'</h2><p>Stock: '.(int)$p['stock'].'</p><form method="post" action="index.php?page=cart">'.csrf_field().'<input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="'.$id.'"><input type="number" name="qty" min="1" max="'.max(1,(int)$p['stock']).'" value="1"><button class="btn">Add to Cart</button></form></div></div>';break;
case 'cart':echo '<h1>Shopping Cart</h1>'; $cart=cart_items();if(!$cart){echo '<p>Your cart is empty.</p>';break;} $total=0;foreach($cart as $id=>$line){$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$id]);$p=$s->fetch();if(!$p)continue;$lineTotal=(float)$p['price']*(int)$line['qty'];$total+=$lineTotal;echo '<div class="cart-row"><span>'.e($p['name']).' × '.(int)$line['qty'].'</span><b>'.money($lineTotal).'</b><form method="post">'.csrf_field().'<input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="'.$id.'"><button class="btn danger">Remove</button></form></div>'; }echo '<h2>Total: '.money($total).'</h2><a class="btn" href="index.php?page=checkout">Proceed to Checkout</a>';break;
case 'checkout':require_login();if(!cart_items()){echo '<h1>Cart is empty</h1>';break;}echo '<h1>Checkout</h1><form method="post" class="form-card">'.csrf_field().'<label>Full name<input name="customer_name" required value="'.e(current_user()['name']).'"></label><label>Phone<input name="phone" required></label><label>Delivery address<textarea name="address" required></textarea></label><label>City<input name="city" required value="Faisalabad"></label><label>Shipping fee (PKR)<input type="number" name="shipping_fee" min="0" value="0"></label><label>Payment method<select name="payment_method"><option value="cod">Cash on Delivery</option><option value="bank_transfer">Bank Transfer (manual verification)</option><option value="jazzcash">JazzCash (manual verification)</option><option value="easypaisa">Easypaisa (manual verification)</option></select></label><button class="btn">Place Order</button></form>';break;
case 'login':echo '<h1>Customer Login</h1><form method="post" class="form-card">'.csrf_field().'<label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Login</button><p><a href="index.php?page=register">Create account</a></p></form>';break;
case 'register':echo '<h1>Create Account</h1><form method="post" class="form-card">'.csrf_field().'<label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (10+ characters)<input type="password" name="password" minlength="10" required></label><button class="btn">Register</button></form>';break;
case 'account':require_login();echo '<h1>My Account</h1><p>Welcome, '.e(current_user()['name']).'</p><a class="btn" href="index.php?page=orders">My Orders</a>';break;
case 'orders':require_login();$s=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([current_user()['id']]);echo '<h1>My Orders</h1>';foreach($s->fetchAll() as $o)echo '<div class="cart-row"><b>'.e($o['order_number']).'</b><span>'.e($o['order_status']).'</span><strong>'.money($o['total']).'</strong></div>';break;
case 'track':echo '<h1>Track Order</h1><form method="get" class="form-card"><input type="hidden" name="page" value="track"><label>Order number<input name="order" required value="'.e($_GET['order']??'').'"></label><button class="btn">Track</button></form>';if(!empty($_GET['order'])){$s=db()->prepare('SELECT order_number,order_status,created_at FROM orders WHERE order_number=?');$s->execute([$_GET['order']]);$o=$s->fetch();echo $o?'<p>'.e($o['order_number']).' — '.e($o['order_status']).'</p>':'<p>Order not found.</p>';}break;
case 'wishlist':case 'compare':echo '<h1>'.e($pageTitle).'</h1><p>Sign in and add products from product pages. This section is ready for saved items.</p>';break;
case 'contact':echo '<h1>Contact Us</h1><p>'.e(APP_LOCATION).' · '.e(APP_PHONE).'</p>';break;
case '404':http_response_code(404);echo '<h1>404 — Page not found</h1>';break;
default:
 $slug=$page;$s=db()->prepare('SELECT * FROM pages WHERE slug=? AND is_published=1');$s->execute([$slug]);$content=$s->fetch();if($content){echo '<h1>'.e($content['title']).'</h1><article class="prose">'.nl2br(e($content['content'])).'</article>';}else echo '<h1>'.e($pageTitle).'</h1><p>Information will be published here by the store administrator.</p>';
}
function render_products(array $products): void { if(!$products){echo '<p class="empty">No products found. Please check back soon.</p>';return;}echo '<div class="product-grid">';foreach($products as $p){$price=$p['sale_price']?:$p['price'];echo '<article class="product-card"><a href="index.php?page=product&id='.(int)$p['id'].'"><div class="prod-image">'.($p['image']?'<img src="'.e(url($p['image'])).'" alt="'.e($p['name']).'">':'🛍️').'</div><div class="prod-info"><small>'.e($p['sku']).'</small><h3>'.e($p['name']).'</h3><b>'.money($price).'</b></div></a><form method="post" action="index.php?page=cart">'.csrf_field().'<input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="'.(int)$p['id'].'"><button class="btn full" '.((int)$p['stock']<1?'disabled':'').'>Add to Cart</button></form></article>'; }echo '</div>'; }
require __DIR__.'/includes/footer.php';
